# Check whether any marker-stamp placements overlap the original motif bbox and print placements/collisions.
markers=[(5,12),(8,22),(9,14),(13,15),(14,10),(15,18),(19,7),(22,14),(24,21)]
for r,c in markers:
 cells={(r-1,c-1),(r-1,c),(r,c-1),(r,c),(r,c+1),(r+1,c-1)}
 print((r,c), sorted(cells & {(rr,cc) for rr in range(12,15) for cc in range(5,8)}))

# Check motif centroid / anchor in the demos, using coordinates relative to motif bbox.
examples={
'demo1':[(0,0),(0,1),(1,0),(1,1),(2,0),(2,1)],
'demo2':[(r,c) for r in range(3) for c in range(3)],
'test':[(0,0),(0,1),(1,0),(1,1),(1,2),(2,0)]}
for name,pts in examples.items():
 print(name,tuple(sum(p[i] for p in pts)/len(pts) for i in range(2)))
